// ════════════════════════════════════════════════════════
// iFleetPro — Custom PDF Font (DejaVu Sans subset)
// ════════════════════════════════════════════════════════════════════
//
// Subset of DejaVu Sans containing ASCII + Latin Extended + ₵ (U+20B5).
// Used by jsPDF to render the Ghana Cedi symbol in PDF reports.
// ────────────────────────────────────────────────────────────────────

import jsPDF from 'jspdf'

const FONT_FAMILY = 'DejaVuSans'

const REGULAR_B64 = ''

const BOLD_B64 = ''

/** Register DejaVu Sans fonts with a jsPDF instance. Call once per document. */
export function registerFonts(doc: jsPDF): void {
  try {
    doc.addFileToVFS('DejaVuSans-Regular.ttf', REGULAR_B64)
    doc.addFont('DejaVuSans-Regular.ttf', FONT_FAMILY, 'normal')

    doc.addFileToVFS('DejaVuSans-Bold.ttf', BOLD_B64)
    doc.addFont('DejaVuSans-Bold.ttf', FONT_FAMILY, 'bold')

    doc.setFont(FONT_FAMILY)
  } catch {
    // Fallback: if font registration fails, continue with default font
    // Currency symbol may render as µ instead of ₵
  }
}

/** Get the registered font family name */
export function getFontFamily(): string {
  return FONT_FAMILY
}
